const $=s=>document.querySelector(s), KEY='compass-bc-v1';
const names=['English Studies 12','English First Peoples 12','Pre-Calculus 12','Calculus 12','Physics 12','Chemistry 12','Anatomy and Physiology 12','Computer Science 12','Economics 12','Social Studies 12','其他学术课程'];
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}state=Object.assign({profile:{grade:'11',identity:'国际学生',year:'2028',budget:'50000'},courses:[],answers:{},done:false,saved:[]},state||{});
let page='home',filter='全部';const tabs=[['home','⌂','规划总览'],['profile','◎','我的档案'],['quiz','✳','兴趣测评'],['grades','▤','课程与成绩'],['majors','◈','专业探索'],['schools','▥','院校路径'],['simulate','↗','情景模拟'],['report','☷','我的报告']];
const questions=[['我喜欢拆解设备、制作模型或动手解决问题。','R'],['我愿意花时间理解数学、科学或数据背后的规律。','I'],['我喜欢写作、视觉设计或创作新的表达方式。','A'],['帮助别人理解问题、学习或成长会让我有成就感。','S'],['我喜欢组织活动、提出方案并说服别人参与。','E'],['我喜欢整理资料、核对细节和建立清晰的流程。','C'],['我愿意通过反复实验改进一个实际作品。','R'],['面对复杂问题，我倾向先研究证据和原因。','I'],['比起固定步骤，我更喜欢开放的创意任务。','A'],['我愿意倾听他人的经历并一起寻找办法。','S'],['我对商业决策、资源分配或创业感兴趣。','E'],['我享受用表格、计划和规则让事情井然有序。','C']];
const types={R:'实践',I:'研究',A:'创意',S:'助人',E:'领导',C:'条理'};
const majors=[{id:'engineering',name:'工程与应用科学',en:'Engineering',type:['R','I'],courses:[2,4,5],desc:'用数学、物理与设计解决现实问题。探索机械、电气、土木等方向。',task:'用简单材料设计一座桥，记录载重测试与改进。'},{id:'computing',name:'计算机与数据',en:'Computing & Data',type:['I','R'],courses:[2,3,7],desc:'探索算法、软件、数据分析与计算思维。不同院校的入学路径需要分别核对。',task:'做一个小型网页或数据可视化，记录调试过程。'},{id:'business',name:'商科与经济',en:'Business & Economics',type:['E','C'],courses:[2,8,0],desc:'理解组织、市场与决策，探索会计、金融、营销和经济学。',task:'采访一家小店，分析客户需求与成本结构。'},{id:'life',name:'生命与健康科学',en:'Life & Health Sciences',type:['I','S'],courses:[5,6,2],desc:'探索生命系统、健康与实验研究。本科方向与后续职业资格须分别规划。',task:'阅读一篇科普研究，梳理问题、方法和证据。'},{id:'social',name:'社会科学与心理',en:'Social Sciences',type:['S','I'],courses:[0,9,2],desc:'研究人类行为、社会与公共议题，兼顾写作、研究和数据能力。',task:'设计一份匿名小调查，讨论抽样与结论的局限。'},{id:'arts',name:'人文、设计与传播',en:'Arts & Communication',type:['A','S'],courses:[0,9],desc:'探索语言、历史、媒介与设计，形成表达能力和个人作品。',task:'围绕一个社区问题，制作短文、海报或视频。'}];
const schools=[['UBC','英属哥伦比亚大学','BC','https://you.ubc.ca/applying-ubc/requirements/','按校区、学位及后续专业路径分别规划。'],['SFU','西蒙菲莎大学','BC','https://www.sfu.ca/students/admission/admission-requirements/','按学院与项目核对课程、英语及补充材料要求。'],['Waterloo','滑铁卢大学','ON','https://uwaterloo.ca/future-students/admissions/admission-requirements','按具体项目核对先修课程和补充申请。'],['Toronto','多伦多大学','ON','https://future.utoronto.ca/requirements-canadian-high-schools','区分校区、入学类别与后续专业选择。'],['McGill','麦吉尔大学','QC','https://www.mcgill.ca/undergraduate-admissions/apply','按BC课程背景与学院核对申请要求。'],['UVic','维多利亚大学','BC','https://www.uvic.ca/undergraduate/admissions/index.php','补充BC本地探索路径，按项目核对要求。'],['Alberta','阿尔伯塔大学','AB','https://www.ualberta.ca/en/admissions/how-to-apply/admission-requirements/index.html','按项目核对指定的12年级课程组合。'],['McMaster','麦克马斯特大学','ON','https://future.mcmaster.ca/apply/requirements/','按具体课程背景及项目查询入学条件。']];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saved').textContent='已保存在此浏览器'}catch{toast('浏览器存储不可用，请导出报告保留结果')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function go(p){page=p;render();window.scrollTo(0,0)}
function title(k,t,d){return `<div class="top"><div class="eyebrow">${k}</div><h1>${t}</h1><p class="muted">${d}</p></div>`}
function scores(){let s={R:0,I:0,A:0,S:0,E:0,C:0};questions.forEach((q,i)=>{s[q[1]]+=Number(state.answers[i]||0)});return s}
function ranked(){let s=scores();return [...majors].sort((a,b)=>b.type.reduce((v,t)=>v+s[t],0)-a.type.reduce((v,t)=>v+s[t],0))}
function average(cs=state.courses){const c=cs.filter(x=>x.status!=='计划修读'&&x.mark!==''&&Number.isFinite(Number(x.mark)));return c.length?Math.round(c.reduce((a,x)=>a+Number(x.mark),0)/c.length):null}
function filled(){return Object.keys(state.answers).length}
function missing(m,cs=state.courses){return m.courses.filter(i=>!cs.some(c=>c.name===names[i]))}
function home(){return `<section class="hero"><div><div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h1>找到方向，走出自己的路径。</h1><p>将兴趣、BC课程与学术表现连接起来。<br>一步步探索适合你的加拿大本科方向。</p><button class="primary" onclick="go('${state.done?'report':'quiz'}')">${state.done?'查看我的探索报告':'开始认识自己'} ↗</button> <button class="secondary" onclick="demo()">体验示例档案</button></div><div class="hero-art"><div class="orbit"></div><span class="arrow">↑</span><i class="dot"></i><span class="art-label">N 49° · 看见更多可能</span></div></section><div class="section-title"><h2>你的规划，从这三步开始</h2><span>按照自己的节奏，逐步完善</span></div><div class="grid">${[['quiz','01','认识自己','12道兴趣探索题，找到喜欢投入的活动与学习方式。',state.done?'已完成':`${filled()}/12 已回答`],['grades','02','了解学术准备','记录BC课程、校内成绩与计划选课，发现准备缺口。',`${state.courses.length} 门课程`],['simulate','03','探索未来路径','调整选课与目标成绩，看看专业准备如何变化。','开始模拟']].map(x=>`<article class="card"><div class="step"><span class="icon">${x[1]}</span><span class="badge">${x[4]}</span></div><h3>${x[2]}</h3><p>${x[3]}</p><button class="link" onclick="go('${x[0]}')">进入${x[2]} →</button></article>`).join('')}</div><div class="section-title"><h2>把可能，变成下一步</h2><span>兴趣 × 学术 × 路径</span></div><div class="split"><div class="card"><div class="row"><h3>我的准备进度</h3><span class="pill">BC课程路径</span></div>${[['兴趣探索',state.done?100:filled()/12*100],['课程档案',Math.min(100,state.courses.length/6*100)]].map(x=>`<div class="row"><span>${x[0]}</span><small>${Math.round(x[1])}%</small></div><div class="bar"><i style="width:${x[1]}%"></i></div>`).join('')}<p>进度仅表示档案完整程度，不代表申请竞争力。</p></div><div class="card" style="background:#f0f2e9"><span class="eyebrow">A SMALL STEP THIS WEEK</span><h3 style="margin-top:16px">先体验，再决定。</h3><p>选一个感兴趣的专业，用一次小项目验证：你是否喜欢它真正的学习过程？</p><button class="link" onclick="go('majors')">寻找一个探索任务 ↗</button></div></div>`}
function profile(){const p=state.profile;return title('MY PROFILE','先从你的学习背景开始','学习课程与申请身份分别记录。第一版适用于普通BC高中课程路径。')+`<div class="card"><div class="fields"><label>当前年级<select onchange="setProfile('grade',this.value)">${['10','11','12'].map(x=>`<option ${p.grade===x?'selected':''}>${x}</option>`).join('')}</select></label><label>申请身份<select onchange="setProfile('identity',this.value)">${['国际学生','加拿大公民 / 永久居民','尚未确定'].map(x=>`<option ${p.identity===x?'selected':''}>${x}</option>`).join('')}</select></label><label>预计大学入学年份<select onchange="setProfile('year',this.value)">${['2027','2028','2029','2030'].map(x=>`<option ${p.year===x?'selected':''}>${x}</option>`).join('')}</select></label><label>年度预算（加元，含学费与生活费）<input type="number" min="0" max="300000" value="${esc(p.budget)}" onchange="setProfile('budget',this.value)"></label></div><div class="note">当前课程体系：BC Dogwood。预算与身份用于报告背景展示；本版尚未接入各校费用计算或英语豁免判断。</div><div class="actions"><button class="primary" onclick="go('quiz')">保存并探索兴趣 →</button><button class="secondary" onclick="resetData()">清除本地档案</button></div></div>`}
function setProfile(k,v){if(k==='budget'&&(!Number.isFinite(+v)||+v<0||+v>300000)){toast('请输入0到300000之间的预算');render();return}state.profile[k]=v;save()}
function quiz(){return title('DISCOVER YOURSELF','什么事情，会让你主动投入？','12题简版活动兴趣探索，参考RIASEC六类兴趣组织；属于自编探索问卷，未经心理测量验证。')+`<div class="card"><div class="row"><b>按真实偏好作答，没有标准答案</b><span id="qprogress" class="badge">${filled()} / 12</span></div>${questions.map((q,i)=>`<div class="q"><b>${String(i+1).padStart(2,'0')}.</b> ${q[0]}<div class="choices">${['不喜欢','较少喜欢','一般','比较喜欢','非常喜欢'].map((s,j)=>`<button aria-label="第${i+1}题：${s}" aria-pressed="${state.answers[i]===j+1}" class="${state.answers[i]===j+1?'selected':''}" onclick="answer(${i},${j+1},this)">${s}</button>`).join('')}</div></div>`).join('')}<div class="actions"><button class="primary" onclick="finishQuiz()">生成兴趣画像 →</button></div><p>兴趣会随经验变化。结果用于探索，不用于诊断人格或限制专业选择。</p></div>`}
function answer(i,v,el){state.answers[i]=v;state.done=false;save();el.parentNode.querySelectorAll('button').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});el.classList.add('selected');el.setAttribute('aria-pressed','true');$('#qprogress').textContent=filled()+' / 12'}
function finishQuiz(){if(filled()<12){toast('还有 '+(12-filled())+' 道题未完成');return}state.done=true;save();go('report')}
function grades(){return title('ACADEMIC SNAPSHOT','让课程，连接未来的选择。','记录已完成、在修与计划修读的课程。仅计划修读不代表已经满足入学条件。')+`<div class="card"><div class="row"><h2>我的BC课程清单</h2><button class="secondary tiny" onclick="addCourse()">＋ 添加课程</button></div><div class="course muted"><span>课程名称</span><span>成绩 %</span><span>状态</span><span></span></div>${state.courses.length?state.courses.map((c,i)=>`<div class="course"><label><select aria-label="第${i+1}门课程名称" onchange="updateCourse(${i},'name',this.value)">${names.map(n=>`<option ${n===c.name?'selected':''}>${n}</option>`).join('')}</select></label><label><input aria-label="${esc(c.name)}成绩" type="number" min="0" max="100" placeholder="未出分" value="${esc(c.mark)}" onchange="updateCourse(${i},'mark',this.value)"></label><label><select aria-label="${esc(c.name)}状态" onchange="updateCourse(${i},'status',this.value)">${['在修','已完成','计划修读'].map(s=>`<option ${s===c.status?'selected':''}>${s}</option>`).join('')}</select></label><button class="delete" aria-label="删除${esc(c.name)}" onclick="state.courses.splice(${i},1);save();render()">×</button></div>`).join(''):`<div class="empty"><h3>还没有课程记录</h3><p>从English 12和当前最关心的学科开始添加。</p><button class="primary" onclick="addCourse()">添加第一门课程</button></div>`}<div class="note">此处平均分只是已录入的在修/已完成课程的算术平均，不是任何大学的录取均分。本版重点记录12年级课程，不执行完整毕业审核。</div><div class="actions"><button class="primary" onclick="go('simulate')">保存并模拟选课 →</button></div></div><div class="card" style="margin-top:20px"><h3>毕业条件与大学条件，要分别检查</h3><p>BC普通毕业路径要求至少80个课程学分，并完成省级读写与数学评估。完整必修结构、原住民主题课程等要求，请与学校辅导员核对。</p><a href="https://curriculum.gov.bc.ca/graduation" target="_blank" rel="noopener">查看BC教育部门官方说明 ↗</a></div>`}
function addCourse(){const n=names.find(n=>!state.courses.some(c=>c.name===n));if(!n){toast('已添加全部示例课程');return}state.courses.push({name:n,mark:'',status:'在修'});save();render()}
function updateCourse(i,k,v){if(k==='mark'&&v!==''&&(!Number.isFinite(+v)||+v<0||+v>100)){toast('成绩应在0—100之间');render();return}if(k==='name'&&state.courses.some((c,j)=>j!==i&&c.name===v)){toast('该课程已在清单中');render();return}state.courses[i][k]=v;save()}
function majorCard(m){const saved=state.saved.includes(m.id);return `<article class="card"><div class="row"><span class="eyebrow">${m.en}</span><button class="link" aria-label="收藏${m.name}" onclick="toggleMajor('${m.id}')">${saved?'★ 已收藏':'☆ 收藏'}</button></div><h2 style="margin-top:18px">${m.name}</h2><span class="badge">${m.type.map(t=>types[t]).join(' · ')}兴趣</span><p>${m.desc}</p><details><summary>学习准备与体验任务</summary><p>建议了解的课程（非通用入学要求）：${m.courses.map(i=>names[i]).join('、')}</p><p>探索任务：${m.task}</p></details><div class="actions"><button class="link" onclick="go('schools')">探索院校路径 →</button></div></article>`}
function toggleMajor(id){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render()}
function explore(){return title('EXPLORE POSSIBILITIES','先看见方向，再理解选择。','六个专业大类用于第一轮探索。排序仅参考兴趣回答，不代表能力、职业适合度或录取机会。')+(state.done?'':`<div class="note">完成兴趣测评后，可按你的兴趣回答排序。目前为默认展示。</div>`)+`<div class="programs">${(state.done?ranked():majors).map(majorCard).join('')}</div>`}
function schoolView(){return title('CANADIAN UNIVERSITY PATHWAYS','从BC课堂，走向加拿大大学。','首批八所院校。目录与官方入口已接入；详细规则目前仅提供UBC温哥华工程路径示例。')+`<div class="switches">${['全部','BC','ON','QC','AB'].map(s=>`<button class="${filter===s?'active':''}" onclick="filter='${s}';render()">${s}</button>`).join('')}</div><div class="programs">${schools.filter(s=>filter==='全部'||s[2]===filter).map(s=>`<div class="card"><div class="row"><span class="eyebrow">${s[0]}</span><span class="pill">${s[2]}</span></div><h2 style="margin-top:18px">${s[1]}</h2><p>${s[4]}</p><span class="badge ${s[0]==='UBC'?'':'warn'}">${s[0]==='UBC'?'工程：课程检查示例':'项目细则待录入'}</span><p>目录收录不表示已完成所有项目的招生规则核验。</p><a href="${s[3]}" target="_blank" rel="noopener">官方申请要求 ↗</a>${s[0]==='UBC'?`<div class="actions"><button class="primary tiny" onclick="go('simulate')">检查工程准备</button></div>`:''}</div>`).join('')}</div>`}
function engineering(cs){const req=[['English Studies 12','English First Peoples 12'],['Pre-Calculus 12'],['Physics 12'],['Chemistry 12']];return req.map(a=>{const c=cs.find(c=>a.includes(c.name));return {label:a.join(' / '),c,text:!c?'未录入':c.status==='计划修读'?'计划修读，尚未完成':c.status==='在修'?'在修，最终成绩待定':'已完成（自报）'}})}
function ruleHTML(cs){return engineering(cs).map(r=>`<div class="result-line"><span class="circle">${r.c?r.c.status==='已完成'?'✓':'◷':'!'}</span><div><b>${esc(r.label)}</b><br><span class="${!r.c?'warning':'muted'}">${r.text}${r.c&&r.c.mark!==''?' · '+esc(r.c.mark)+'%':''}</span></div></div>`).join('')}
function simulate(){return title('WHAT IF LAB','如果改变一步，路径会怎样？','在副本里调整课程与成绩，比较准备情况。模拟不会覆盖真实课程档案。')+`<div class="split"><section class="card"><span class="eyebrow">SCENARIO BUILDER</span><h2 style="margin-top:14px">UBC Vancouver · 工程示例</h2><p>从高中申请工程；具体工程专业的后续分流需另行核对。</p><label>数学目标成绩 <b id="targetLabel">90%</b><input id="target" type="range" min="0" max="100" value="90" oninput="$('#targetLabel').textContent=this.value+'%';runSim()"></label><label class="checkline"><input id="addPhysics" type="checkbox" onchange="runSim()">将 Physics 12 加入计划修读</label><label class="checkline"><input id="addChem" type="checkbox" onchange="runSim()">将 Chemistry 12 加入计划修读</label><label class="checkline"><input id="addMath" type="checkbox" onchange="runSim()">将 Pre-Calculus 12 加入计划修读</label><div class="note">拖动目标成绩仅改变模拟数值，不推算录取机会。计划课程仍是待完成条件。</div><div class="actions"><button class="secondary" onclick="render()">重置模拟</button><button class="primary" onclick="go('grades')">编辑真实课程 →</button></div></section><section class="card"><div class="row"><h3>当前 → 模拟</h3><span class="badge">准备条件对比</span></div><div id="simResult"></div></section></div><div class="card" style="margin-top:20px"><h3>规则依据与边界</h3><p>UBC工程官方日历列出BC 12年级数学、物理、化学及英语相关要求。此处只检查常见课程是否出现在清单，不审核全部大学通用要求、11年级课程、英语能力、个人陈述或竞争性筛选。缺少物理/化学的特殊情况应直接咨询招生部门。</p><a href="https://vancouver.calendar.ubc.ca/faculties-colleges-and-schools/faculty-applied-science/bachelor-applied-science/admission" target="_blank" rel="noopener">UBC工程官方录取说明 ↗</a><p>核验日期：2026-10-24 · 满足最低条件不保证录取。</p></div>`}
function runSim(){let cs=state.courses.map(c=>({...c}));const target=+$('#target').value;[['addPhysics',4],['addChem',5],['addMath',2]].forEach(([id,i])=>{if($('#'+id).checked&&!cs.some(c=>c.name===names[i]))cs.push({name:names[i],mark:'',status:'计划修读'})});const math=cs.find(c=>c.name===names[2]);if(math)math.mark=target;const before=engineering(state.courses),after=engineering(cs),n=rs=>rs.filter(r=>r.c).length;$('#simResult').innerHTML=`<div class="row"><div><span class="muted">清单包含的课程项</span><div class="big-number">${n(before)} <span class="muted">→</span> ${n(after)}<small style="font-size:14px"> / 4</small></div></div></div><p class="muted">课程出现不等于满足完整录取条件。</p>${ruleHTML(cs)}<div class="note">${math?`数学目标：${target}%。${math.status==='计划修读'?'该课程仍待修读。':'这是情景目标，不是已取得成绩。'}`:'数学课程尚未加入，目标分数未应用。'}<br>${n(after)>n(before)?'模拟补充了课程计划；下一步确认学校开课、先修关系与完成时间。':'可尝试补充缺失课程，或与辅导员讨论替代方案。'}</div>`}
function report(){const s=scores(),sorted=Object.keys(s).sort((a,b)=>s[b]-s[a]),av=average();return title('YOUR PATHWAY REPORT','一份可以持续更新的探索地图。',`${state.profile.grade}年级 · BC课程 · ${state.profile.identity} · 计划${state.profile.year}入学`)+`<div class="actions" style="margin-bottom:20px"><button class="primary" onclick="window.print()">打印 / 保存PDF</button><button class="secondary" onclick="download()">导出档案JSON</button></div><div class="metrics"><div class="metric"><span>兴趣探索</span><strong>${state.done?sorted.slice(0,2).map(t=>types[t]).join(' / '):'待完成'}</strong></div><div class="metric"><span>自报课程平均</span><strong>${av===null?'—':av+'%'}</strong></div><div class="metric"><span>已记录课程</span><strong>${state.courses.length}<small> 门</small></strong></div></div><div class="split"><div class="card"><h2>我的兴趣画像</h2>${state.done?Object.entries(types).map(([k,v])=>`<div class="row"><span>${v} ${k}</span><small>${s[k]} / 10</small></div><div class="bar"><i style="width:${s[k]*10}%"></i></div>`).join(''):`<p>完成12道题后显示你的活动兴趣分布。</p><button class="primary" onclick="go('quiz')">开始测评</button>`}<p>原始分数反映本问卷中的偏好，不是常模百分位。并列分数应同等考虑。</p></div><div class="card"><h2>接下来，做三件小事</h2><div class="list-item"><b>01 · ${state.done?'验证一个兴趣方向':'完成兴趣探索'}</b><small>${state.done?ranked()[0].task:'用真实偏好回答，暂时放下学校排名。'}</small></div><div class="list-item"><b>02 · 完善课程档案</b><small>核对成绩单与计划课程，区分在修和已完成。</small></div><div class="list-item"><b>03 · 核对目标项目</b><small>确认先修课程、英语要求、补充材料和入学后的专业路径。</small></div><p>预算背景：CAD ${Number(state.profile.budget).toLocaleString()} / 年。本版未估算各校实际费用。</p></div></div><div class="section-title"><h2>${state.done?'值得优先体验的方向':'专业方向预览'}</h2><span>先体验，再决定</span></div><div class="programs">${(state.done?ranked():majors).slice(0,2).map(majorCard).join('')}</div><div class="note">此报告由问卷分数与显式课程规则生成，未接入生成式AI或完整招生数据库。不构成录取预测。平均分不是院校录取均分；兴趣推荐不是正式心理评估。</div>`}
function download(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='MaplePath-BC-profile.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function demo(){state.profile={grade:'11',identity:'国际学生',year:'2028',budget:'65000'};state.courses=[{name:names[0],mark:84,status:'在修'},{name:names[2],mark:91,status:'在修'},{name:names[5],mark:88,status:'已完成'},{name:names[7],mark:93,status:'在修'}];state.answers=Object.fromEntries(questions.map((q,i)=>[i,[4,5,3,3,4,3,4,5,3,3,4,3][i]]));state.done=true;save();render();toast('已载入示例档案，可修改体验')}
function resetData(){if(confirm('清除保存在此浏览器的全部档案？')){localStorage.removeItem(KEY);state={profile:{grade:'11',identity:'国际学生',year:'2028',budget:'50000'},courses:[],answers:{},done:false,saved:[]};go('home')}}
function render(){$('#nav').innerHTML=tabs.map(([id,ico,t])=>`<button class="${page===id?'active':''}" ${page===id?'aria-current="page"':''} onclick="go('${id}')"><span>${ico}</span>${t}</button>`).join('');$('#app').innerHTML=({home,profile,quiz,grades,majors:explore,schools:schoolView,simulate,report}[page])();if(page==='simulate')runSim()}
render();
